        impl < K , V , S , const N : usize > IndexMap < K , V , S , N > where K : Eq + Hash , S : BuildHasher , { # [doc = " Returns an entry for the corresponding key"] # [doc = " ```"] # [doc = " use heapless::index_map::Entry;"] # [doc = " use heapless::index_map::FnvIndexMap;"] # [doc = " let mut map = FnvIndexMap::<_, _, 16>::new();"] # [doc = " if let Entry::Vacant(v) = map.entry(\"a\") {"] # [doc = "     v.insert(1).unwrap();"] # [doc = " }"] # [doc = " if let Entry::Occupied(mut o) = map.entry(\"a\") {"] # [doc = "     println!(\"found {}\", *o.get()); // Prints 1"] # [doc = "     o.insert(2);"] # [doc = " }"] # [doc = " // Prints 2"] # [doc = " println!(\"val: {}\", *map.get(\"a\").unwrap());"] # [doc = " ```"] pub fn entry (& mut self , key : K) -> Entry < '_ , K , V , N > { let hash_val = hash_with (& key , & self . build_hasher) ; if let Some ((probe , pos)) = self . core . find (hash_val , & key) { Entry :: Occupied (OccupiedEntry { key , probe , pos , core : & mut self . core , }) } else { Entry :: Vacant (VacantEntry { key , hash_val , core : & mut self . core , }) } } # [doc = " Returns a reference to the value corresponding to the key."] # [doc = ""] # [doc = " The key may be any borrowed form of the map's key type, but `Hash` and `Eq` on the borrowed"] # [doc = " form *must* match those for the key type."] # [doc = ""] # [doc = " Computes in *O*(1) time (average)."] # [doc = ""] # [doc = " ```"] # [doc = " use heapless::index_map::FnvIndexMap;"] # [doc = ""] # [doc = " let mut map = FnvIndexMap::<_, _, 16>::new();"] # [doc = " map.insert(1, \"a\").unwrap();"] # [doc = " assert_eq!(map.get(&1), Some(&\"a\"));"] # [doc = " assert_eq!(map.get(&2), None);"] # [doc = " ```"] pub fn get < Q > (& self , key : & Q) -> Option < & V > where K : Borrow < Q > , Q : ? Sized + Hash + Eq , { self . find (key) . map (| (_ , found) | unsafe { & self . core . entries . get_unchecked (found) . value }) } # [doc = " Returns true if the map contains a value for the specified key."] # [doc = ""] # [doc = " The key may be any borrowed form of the map's key type, but `Hash` and `Eq` on the borrowed"] # [doc = " form *must* match those for the key type."] # [doc = ""] # [doc = " Computes in *O*(1) time (average)."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use heapless::index_map::FnvIndexMap;"] # [doc = ""] # [doc = " let mut map = FnvIndexMap::<_, _, 8>::new();"] # [doc = " map.insert(1, \"a\").unwrap();"] # [doc = " assert_eq!(map.contains_key(&1), true);"] # [doc = " assert_eq!(map.contains_key(&2), false);"] # [doc = " ```"] pub fn contains_key < Q > (& self , key : & Q) -> bool where K : Borrow < Q > , Q : ? Sized + Eq + Hash , { self . find (key) . is_some () } # [doc = " Returns a mutable reference to the value corresponding to the key."] # [doc = ""] # [doc = " The key may be any borrowed form of the map's key type, but `Hash` and `Eq` on the borrowed"] # [doc = " form *must* match those for the key type."] # [doc = ""] # [doc = " Computes in *O*(1) time (average)."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use heapless::index_map::FnvIndexMap;"] # [doc = ""] # [doc = " let mut map = FnvIndexMap::<_, _, 8>::new();"] # [doc = " map.insert(1, \"a\").unwrap();"] # [doc = " if let Some(x) = map.get_mut(&1) {"] # [doc = "     *x = \"b\";"] # [doc = " }"] # [doc = " assert_eq!(map[&1], \"b\");"] # [doc = " ```"] pub fn get_mut < 'v , Q > (& 'v mut self , key : & Q) -> Option < & 'v mut V > where K : Borrow < Q > , Q : ? Sized + Hash + Eq , { if let Some ((_ , found)) = self . find (key) { Some (unsafe { & mut self . core . entries . get_unchecked_mut (found) . value }) } else { None } } # [doc = " Returns a tuple of references to the key and the value corresponding to the index."] # [doc = ""] # [doc = " Computes in *O*(1) time (average)."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use heapless::index_map::FnvIndexMap;"] # [doc = ""] # [doc = " let mut map = FnvIndexMap::<_, _, 16>::new();"] # [doc = " map.insert(1, \"a\").unwrap();"] # [doc = " assert_eq!(map.get_index(0), Some((&1, &\"a\")));"] # [doc = " assert_eq!(map.get_index(1), None);"] # [doc = " ```"] pub fn get_index (& self , index : usize) -> Option < (& K , & V) > { self . core . entries . get (index) . map (| entry | (& entry . key , & entry . value)) } # [doc = " Returns a tuple of references to the key and the mutable value corresponding to the index."] # [doc = ""] # [doc = " Computes in *O*(1) time (average)."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use heapless::index_map::FnvIndexMap;"] # [doc = ""] # [doc = " let mut map = FnvIndexMap::<_, _, 8>::new();"] # [doc = " map.insert(1, \"a\").unwrap();"] # [doc = " if let Some((_, x)) = map.get_index_mut(0) {"] # [doc = "     *x = \"b\";"] # [doc = " }"] # [doc = " assert_eq!(map[&1], \"b\");"] # [doc = " ```"] pub fn get_index_mut (& mut self , index : usize) -> Option < (& K , & mut V) > { self . core . entries . get_mut (index) . map (| entry | (& entry . key , & mut entry . value)) } # [doc = " Returns the index of the key-value pair corresponding to the key."] # [doc = ""] # [doc = " The key may be any borrowed form of the map's key type, but `Hash` and `Eq` on the borrowed"] # [doc = " form *must* match those for the key type."] # [doc = ""] # [doc = " Computes in *O*(1) time (average)."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use heapless::index_map::FnvIndexMap;"] # [doc = ""] # [doc = " let mut map = FnvIndexMap::<_, _, 8>::new();"] # [doc = " map.insert(1, \"a\").unwrap();"] # [doc = " map.insert(0, \"b\").unwrap();"] # [doc = " assert_eq!(map.get_index_of(&0), Some(1));"] # [doc = " assert_eq!(map.get_index_of(&1), Some(0));"] # [doc = " assert_eq!(map.get_index_of(&2), None);"] # [doc = " ```"] pub fn get_index_of < Q > (& self , key : & Q) -> Option < usize > where K : Borrow < Q > , Q : ? Sized + Hash + Eq , { self . find (key) . map (| (_ , found) | found) } # [doc = " Inserts a key-value pair into the map."] # [doc = ""] # [doc = " If an equivalent key already exists in the map: the key remains and retains in its place in"] # [doc = " the order, its corresponding value is updated with `value` and the older value is returned"] # [doc = " inside `Some(_)`."] # [doc = ""] # [doc = " If no equivalent key existed in the map: the new key-value pair is inserted, last in order,"] # [doc = " and `None` is returned."] # [doc = ""] # [doc = " Computes in *O*(1) time (average)."] # [doc = ""] # [doc = " See also entry if you you want to insert or modify or if you need to get the index of the"] # [doc = " corresponding key-value pair."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use heapless::index_map::FnvIndexMap;"] # [doc = ""] # [doc = " let mut map = FnvIndexMap::<_, _, 8>::new();"] # [doc = " assert_eq!(map.insert(37, \"a\"), Ok(None));"] # [doc = " assert_eq!(map.is_empty(), false);"] # [doc = ""] # [doc = " map.insert(37, \"b\");"] # [doc = " assert_eq!(map.insert(37, \"c\"), Ok(Some(\"b\")));"] # [doc = " assert_eq!(map[&37], \"c\");"] # [doc = " ```"] pub fn insert (& mut self , key : K , value : V) -> Result < Option < V > , (K , V) > { let hash = hash_with (& key , & self . build_hasher) ; match self . core . insert (hash , key , value) { Insert :: Success (inserted) => Ok (inserted . old_value) , Insert :: Full ((k , v)) => Err ((k , v)) , } } # [doc = " Same as [`swap_remove`](Self::swap_remove)"] # [doc = ""] # [doc = " Computes in *O*(1) time (average)."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use heapless::index_map::FnvIndexMap;"] # [doc = ""] # [doc = " let mut map = FnvIndexMap::<_, _, 8>::new();"] # [doc = " map.insert(1, \"a\").unwrap();"] # [doc = " assert_eq!(map.remove(&1), Some(\"a\"));"] # [doc = " assert_eq!(map.remove(&1), None);"] # [doc = " ```"] pub fn remove < Q > (& mut self , key : & Q) -> Option < V > where K : Borrow < Q > , Q : ? Sized + Hash + Eq , { self . swap_remove (key) } # [doc = " Remove the key-value pair equivalent to `key` and return its value."] # [doc = ""] # [doc = " Like `Vec::swap_remove`, the pair is removed by swapping it with the last element of the map"] # [doc = " and popping it off. **This perturbs the position of what used to be the last element!**"] # [doc = ""] # [doc = " Return `None` if `key` is not in map."] # [doc = ""] # [doc = " Computes in *O*(1) time (average)."] pub fn swap_remove < Q > (& mut self , key : & Q) -> Option < V > where K : Borrow < Q > , Q : ? Sized + Hash + Eq , { self . find (key) . map (| (probe , found) | self . core . remove_found (probe , found) . 1) } # [doc = " Retains only the elements specified by the predicate."] # [doc = ""] # [doc = " In other words, remove all pairs `(k, v)` for which `f(&k, &mut v)` returns `false`."] pub fn retain < F > (& mut self , mut f : F) where F : FnMut (& K , & mut V) -> bool , { self . core . retain_in_order (move | k , v | f (k , v)) ; } # [doc = " Shortens the map, keeping the first `len` elements and dropping the rest."] # [doc = ""] # [doc = " If `len` is greater than the map's current length, this has no effect."] # [doc = ""] # [doc = " Computes in *O*(n) time (average)."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use heapless::index_map::FnvIndexMap;"] # [doc = ""] # [doc = " let mut map = FnvIndexMap::<_, _, 8>::new();"] # [doc = " map.insert(3, \"a\").unwrap();"] # [doc = " map.insert(2, \"b\").unwrap();"] # [doc = " map.insert(1, \"c\").unwrap();"] # [doc = " map.truncate(2);"] # [doc = " assert_eq!(map.len(), 2);"] # [doc = " assert_eq!(map.get(&1), None);"] # [doc = ""] # [doc = " let mut iter = map.iter();"] # [doc = " assert_eq!(iter.next(), Some((&3, &\"a\")));"] # [doc = " assert_eq!(iter.next(), Some((&2, &\"b\")));"] # [doc = " assert_eq!(iter.next(), None);"] # [doc = " ```"] pub fn truncate (& mut self , len : usize) { self . core . entries . truncate (len) ; if self . core . indices . len () > self . core . entries . len () { for index in self . core . indices . iter_mut () { match index { Some (pos) if pos . index () >= len => * index = None , _ => () , } } } } # [doc = " Return probe (indices) and position (entries)"] fn find < Q > (& self , key : & Q) -> Option < (usize , usize) > where K : Borrow < Q > , Q : ? Sized + Hash + Eq , { if self . is_empty () { return None ; } let h = hash_with (key , & self . build_hasher) ; self . core . find (h , key) } }
